            " during the process. We will provide you a sample draft email to assist you."
            "\n2. Please clear all Association/Maintenance dues to obtain an NOC (No Objec"
            "tion Certificate) from the Association. The Association will not permit a ne"
            "w occupant to move-in if there are any outstanding dues.\n3. Please add the T"
            "enant's bank account details to your bank account at least one week before t"
            "he move-out date. Banks typically require up to 3 days to process transfers "
            "above Rs. 50,000 when adding a new account. Adding the account in advance en"
            "sures timely refund of the security deposit. We suggest transferring Rs.100 "
            "initially to confirm the details. Please keep us updated.\n4. Please refer to"
            " your rental agreement for any applicable deductions such as painting or cle"
            "aning charges. Our Service Desk team will assist you and the tenant in this "
            "regard.\n5. {{BankAcName}} will conduct the first move-out inspection within "
            "a week to estimate potential deductions from the tenant's security deposit. "
