    {
        "type": "email",
        "label": "Owner 3rd email (Rs.10k buffer + UC price list)",
        "to": "{{OwnerEmail}}",
        "cc": "{{OwnerCC}}",
        "subject": (
            "Don't Miss Out: Prevent Rental Losses & Stress with Early Approval! - {{Soci"
            "ety}} #Flat {{Flat}}"
        ),
        "html": (
            "<div style=\"font-family:'Montserrat','Calibri',Arial,sans-serif;font-size:12"
            "pt;color:#242424;line-height:1.45\"><p>Dear {{OwnerName}},</p><p>I am writing"
            " to discuss a crucial step that will <span style=\"color:#00b050\"><b>ensure p"
            "roper upkeep of your property and help you avoid rental loss and stress.</b>"
            "</span></p><p><b>Potential Losses in Case of Inaction</b></p><ul><li><b>Unse"
            "ttled Accounts with old tenant</b> leading to delays and hassles.</li><li><b"
            ">Vendor Rearrangement</b> resulting in higher costs and difficulty securing "
            "new vendors for minor works.</li><li><b>All Stakeholders (Old tenant, New oc"
            "cupant, vendors and you)</b> are impacted due to <span style=\"color:#ee0000\""
            "><b>minor pending maintenance works</b></span> and increased stress.</li></u"
            "l><p><b>Benefits for You</b></p><ul><li><b>Faster Turnaround</b>: Ensures pe"
            "ace of mind for all the stakeholders</li><li><b>Smoother Handover</b>: New o"
            "ccupants will have a seamless move-in experience.</li><li><b>Avoid Rental Lo"
            "ss and Stress:</b> Timely repairs prevent significant rental income loss and"
            " reduce unnecessary stress.</li><li><b>Efficient Settlement with the Old Ten"
            "ant:</b> Streamlines the process of resolving any issues with the previous t"
            "enant.</li></ul><p><b>Our Ask</b></p><p>We kindly request your <b>early appr"
            "oval for an additional &#8377;10,000 to cover any unforeseen repair costs id"
            "entified during the move-out inspections and during repair works.</b> This p"
            "roactive approval will help you avoid delays and ensure timely handover. Ple"
            "ase note that only the amount actually used from this &#8377;10,000 will be "
            "accounted for, and it will be fairly distributed between you and the tenant "
            "based on the terms of the rental agreement.</p><p><b>Why Early Inspections M"
            "atter</b></p><p>When a tenant/landlord gives us a move-out notice, we conduc"
            "t an initial inspection two to three weeks before move-out. Traditionally, t"
            "hese inspections and repairs were undertaken only after the tenant moved out"
            ", but we are pioneering early move-out inspections. The primary goals of thi"
            "s inspection are to:</p><ol><li>Assess the current condition of the property"
            " and identify necessary repairs</li><li>Estimate repair costs and obtain quo"
            "tes from vendors for the required work</li><li>Determine who is responsible "
            "for these costs (tenant or owner).</li></ol><p>Conducting an early inspectio"
            "n allows tenants to know the tentative repair costs in advance and allows us"
            " to book vendors in advance to complete the repair works as soon as possible"
            " to avoid rental loss. Despite these challenges, early inspections have sign"
            "ificantly reduced disputes and facilitated smoother transitions.</p><p><b>Se"
            "cond Inspection - On the day of move-out</b></p><p>On the tenant&rsquo;s mov"
            "e-out day, we conduct a second inspection. This final inspection often revea"
            "ls additional issues that were not visible during the initial inspection due"
            " to the tenant&rsquo;s belongings. Using the MOBILE app, we digitally docume"
            "nt the property&rsquo;s condition with photos, and compare it with the inspe"
            "ction report during move-in, thus minimizing disputes over damages. However,"
            " at this stage, some more repair works come up for which we again require ap"
            "provals from you. This could take up to a week <span style=\"color:#ee0000\"><"
            "b>TO CALL VENDORS AND GET QUOTES</b></span> and then another week to get a v"
            "endor to complete these newly found issues. The more time spent on this, the"
            " more time your house is empty, thus resulting in rental loss.</p><p><b>Addi"
            "tional issues - Once repair works begin</b></p><p><span style=\"color:#ee0000"
            "\"><b>More issues come up once repair works begin.</b></span> If we wait agai"
            "n for approval, it would result in another delay of up to 2 weeks. All these"
            " lead to overall cost add-up resulting in a significant delay in settling th"
            "e accounts.</p><p><b>Proposal for Streamlined Approval - saving you time and"
            " money</b></p><p>The additional cost which incurs during the second move-out"
            " inspection is hardly Rs. 5,000 of the original estimates (1<sup>st</sup> mo"
            "veout estimate). Moreover, additional costs incurred further during repair w"
            "ork may be another Rs. 5,000. Thus, to minimize delays and ensure the proper"
            "ty is maintained in pristine condition, <b>we propose a default approval of "
            "&#8377;10,000</b> for any additional repairs identified during the final ins"
            "pection and subsequent repair work. However, only the amount actually spent "
            "will be considered, and it will be appropriately split between you and the t"
            "enant based on the rental agreement.</p><p><b>How We Ensure Fairness and Tra"
            "nsparency</b></p><ul><li><b>Photo Documentation:</b> We will provide photogr"
            "aphic evidence of items needing repair.</li><li><b>Reference Point:</b> We h"
            "ave attached the latest price list from Urban Company (<span style=\"color:#e"
            "e0000\">LINK</span>), to give you a rough idea of the cost of each repair wor"
            "k. Repair charges for any additional work carried out will be approximately "
            "within this range, ensuring you are not overcharged.</li></ul><p><b>Your tim"
            "ely approval will streamline the process and ultimately save you time, stres"
            "s and money. Please reply to this email with your consent for the &#8377;10,"
            "000 additional approval for the repair work, for which we have not yet provi"
            "ded a quotation.</b></p><p>Thank you for your understanding and cooperation."
            "</p><p>Warm regards,</p></div>"
        ),
        "body": (
            "Dear {{OwnerName}},\nI am writing to discuss a crucial step that will ensure "
            "proper upkeep of your property and help you avoid rental loss and stress.\n\nP"
            "otential Losses in Case of Inaction\n1. Unsettled Accounts with old tenant le"
            "ading to delays and hassles.\n2. Vendor Rearrangement resulting in higher cos"
            "ts and difficulty securing new vendors for minor works.\n3. All Stakeholders "
            "(Old tenant, New occupant, vendors and you) are impacted due to minor pendin"
            "g maintenance works and increased stress.\n\nBenefits for You\n1. Faster Turnar"
            "ound: Ensures peace of mind for all the stakeholders.\n2. Smoother Handover: "
            "New occupants will have a seamless move-in experience.\n3. Avoid Rental Loss "
            "and Stress: Timely repairs prevent significant rental income loss and reduce"
            " unnecessary stress.\n4. Efficient Settlement with the Old Tenant: Streamline"
            "s the process of resolving any issues with the previous tenant.\n\nOur Ask\nWe "
            "kindly request your early approval for an additional Rs.10,000 to cover any "
            "unforeseen repair costs identified during the move-out inspections and durin"
            "g repair works. This proactive approval will help you avoid delays and ensur"
            "e timely handover. Please note that only the amount actually used from this "
            "Rs.10,000 will be accounted for, and it will be fairly distributed between y"
            "ou and the tenant based on the terms of the rental agreement.\n\nWhy Early Ins"
            "pections Matter\nWhen a tenant/landlord gives us a move-out notice, we conduc"
            "t an initial inspection two to three weeks before move-out. Traditionally th"
            "ese inspections and repairs were undertaken only after the tenant moved out,"
            " but we are pioneering early move-out inspections. The primary goals are to "
            "(1) assess the current condition and identify necessary repairs, (2) estimat"
            "e repair costs and obtain quotes, and (3) determine who is responsible for t"
            "hese costs. Early inspections have significantly reduced disputes and facili"
            "tated smoother transitions.\n\nSecond Inspection - On the day of move-out\nOn t"
            "he tenant's move-out day, we conduct a second inspection. This final inspect"
            "ion often reveals additional issues that were not visible during the initial"
            " inspection due to the tenant's belongings. Using the mobile app, we digital"
            "ly document the property's condition with photos and compare it with the mov"
            "e-in report, minimizing disputes over damages. Some more repair works come u"
            "p at this stage for which we again require your approval - this can take up "
            "to a week to call vendors and get quotes, and another week to complete the w"
            "ork. The more time spent, the longer your house stays empty, resulting in re"
            "ntal loss.\n\nProposal for Streamlined Approval - saving you time and money\nTh"
            "e additional cost during the second move-out inspection is hardly Rs. 5,000 "
            "of the original estimate, and further additional costs during repair work ma"
            "y be another Rs. 5,000. To minimize delays, we propose a default approval of"
            " Rs.10,000 for any additional repairs identified during the final inspection"
            " and subsequent repair work. Only the amount actually spent will be consider"
            "ed, split between you and the tenant per the rental agreement.\n\nHow We Ensur"
            "e Fairness and Transparency\n1. Photo Documentation: We will provide photogra"
            "phic evidence of items needing repair.\n2. Reference Point: We have attached "
            "the latest price list from Urban Company to give you a rough idea of the cos"
            "t of each repair, ensuring you are not overcharged.\n\nYour timely approval wi"
            "ll streamline the process and ultimately save you time, stress and money. Pl"
            "ease reply to this email with your consent for the Rs.10,000 additional appr"
            "oval for the repair work, for which we have not yet provided a quotation.\nTh"
            "ank you for your understanding and cooperation.\n\n[ATTACH: Urban Company pric"
            "e list. A 3-BHK WITHOUT-vs-WITH pre-approval savings table is available in t"
            "he source doc.]\n\nWarm regards,\n{{BankAcName}}\n{{ServiceDesk}}"
        )
    },
